content.css:
.atlyn-cohort-visual {
  box-sizing: border-box;
  color: #242424;
  display: flex;
  flex-direction: column;
  font-family: "Segoe UI", sans-serif;
  font-size: 12px;
  min-height: 0;
  min-width: 0;
  overflow: hidden;
  /* Load-bearing. The <caption> below is absolutely positioned; without a positioned
     ancestor it resolves against the initial containing block, so it belongs to the page
     rather than to the visual and `overflow: hidden` here cannot clip it. */
  position: relative;
  --atlyn-cell-padding: 6px;
  --atlyn-foreground: currentColor;
  --atlyn-background: Canvas;
  --atlyn-foreground-selected: Highlight;
}

.atlyn-status {
  flex: 0 0 auto;
  line-height: 1.4;
  margin: 4px 8px;
  overflow-wrap: anywhere;
}

.atlyn-matrix-viewport {
  flex: 1 1 auto;
  min-height: 0;
  min-width: 0;
  overflow: auto;
  overscroll-behavior: contain;
  touch-action: pan-x pan-y;
}

.atlyn-matrix {
  border-collapse: collapse;
  min-width: max-content;
  table-layout: fixed;
}

/* Screen-reader-only. Size plus `overflow: hidden` alone is not enough: without
   `clip-path` a sliver of the label can still paint, and without `white-space: nowrap`
   a long caption reflows inside the 1px box. Pinned to the root's own origin so the box
   stays inside the bounds the root clips. */
.atlyn-matrix caption {
  border: 0;
  clip-path: inset(50%);
  height: 1px;
  left: 0;
  margin: 0;
  overflow: hidden;
  padding: 0;
  position: absolute;
  top: 0;
  white-space: nowrap;
  width: 1px;
}

.atlyn-matrix th,
.atlyn-matrix td {
  border: 1px solid #d9d9d9;
  min-width: 72px;
  padding: var(--atlyn-cell-padding);
  text-align: right;
  vertical-align: middle;
  white-space: nowrap;
}

.atlyn-matrix th {
  background: #f4f4f4;
  font-weight: 600;
}

/* Sticky positioning is scoped per band on purpose. A shared
   `.atlyn-matrix th { position: sticky; top: 0 }` also pinned every ROW header
   vertically, so scrolling down piled the cohort labels on top of one another at the
   top of the scrollport and covered the period headers. */
.atlyn-matrix thead th {
  position: sticky;
  /* Overridden per header band by src/visual.ts when the Period hierarchy is expanded,
     so nested levels stack instead of collapsing onto the first. */
  top: 0;
  z-index: 3;
}

/* Row headers stick to the inline start ONLY. `top: auto` is the reset that keeps them
   scrolling vertically with their own row; their z-index must stay below the column
   header band they scroll under. */
.atlyn-matrix tbody th {
  left: 0;
  position: sticky;
  text-align: left;
  top: auto;
  z-index: 2;
}

/* The corner label sits where both sticky bands cross, so it pins in both axes and must
   paint above both. */
.atlyn-matrix thead th.atlyn-corner {
  left: 0;
  z-index: 4;
}

.atlyn-matrix td {
  transition: background-color 120ms ease;
}

.atlyn-matrix td.is-highlighted {
  outline: 1px solid currentColor;
  outline-offset: -1px;
}

.atlyn-matrix [aria-selected="true"] {
  outline: 2px solid var(--atlyn-foreground-selected);
  outline-offset: -2px;
}

.atlyn-matrix .is-subtotal {
  font-weight: 600;
}

.atlyn-expand {
  background: transparent;
  border: 0;
  color: inherit;
  cursor: pointer;
  font: inherit;
  margin-inline-end: 4px;
  min-width: 18px;
  padding: 0;
}

.atlyn-matrix td:focus-visible,
.atlyn-matrix th:focus-visible {
  outline: 2px solid currentColor;
  outline-offset: -2px;
}

.atlyn-matrix td.status-future {
  background: repeating-linear-gradient(
    -45deg,
    transparent,
    transparent 5px,
    rgba(128, 128, 128, 0.11) 5px,
    rgba(128, 128, 128, 0.11) 7px
  );
}

.atlyn-matrix td.status-observed-zero {
  color: #666;
}

.atlyn-matrix td.status-invalid {
  background: #fff4f4;
  color: #9b1c1c;
}

.atlyn-empty {
  margin: 16px;
}

.atlyn-load-more {
  align-self: flex-start;
  background: transparent;
  border: 1px solid currentColor;
  color: inherit;
  cursor: pointer;
  margin: 4px 8px;
  padding: 4px 8px;
}

.is-high-contrast {
  background: var(--atlyn-background);
  color: var(--atlyn-foreground);
}

.is-high-contrast .atlyn-matrix th,
.is-high-contrast .atlyn-matrix td {
  background: var(--atlyn-background);
  border-color: var(--atlyn-foreground);
  color: var(--atlyn-foreground);
}

.is-high-contrast .atlyn-matrix td.status-future {
  background: repeating-linear-gradient(
    -45deg,
    var(--atlyn-background),
    var(--atlyn-background) 5px,
    var(--atlyn-foreground) 5px,
    var(--atlyn-foreground) 7px
  );
}

.is-high-contrast .atlyn-matrix td {
  opacity: 1 !important;
}

.is-high-contrast .atlyn-matrix [aria-selected="true"] {
  outline-color: var(--atlyn-foreground-selected);
}

.reduced-motion .atlyn-matrix td {
  transition: none;
}

[dir="rtl"] .atlyn-matrix th,
[dir="rtl"] .atlyn-matrix td {
  text-align: left;
}

[dir="rtl"] .atlyn-matrix tbody th {
  left: auto;
  right: 0;
  text-align: right;
}

[dir="rtl"] .atlyn-matrix thead th.atlyn-corner {
  left: auto;
  right: 0;
}

@media (max-width: 480px) {
  .atlyn-status {
    font-size: 11px;
  }

  .atlyn-matrix th,
  .atlyn-matrix td {
    min-width: 64px;
    padding: max(4px, var(--atlyn-cell-padding));
  }
}
